// Generates src/lib/tool-registry/definitions.generated.ts from the
// definitions/*.tool.json files listed in definitions/manifest.json plus the
// shared policy packs under definitions/_shared/. Every definition is
// Zod-validated at generation time (errors carry the file name); the runtime
// loader trusts the already-validated data. The generated file is committed
// and verify:tool-registry checks for drift.
//
// Run: npm run generate:tool-imports   (also runs in prebuild)
import { createHash } from "node:crypto";
import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath, pathToFileURL } from "node:url";
import { dirname, join, relative, isAbsolute } from "node:path";
import { tsImport } from "tsx/esm/api";

const here = dirname(fileURLToPath(import.meta.url));
const root = join(here, "..");
const defsDir = join(root, "src/lib/tool-registry/definitions");
const manifestPath = join(defsDir, "manifest.json");
const outPath = join(root, "src/lib/tool-registry/definitions.generated.ts");

// Windows: tsImport/ESM loaders reject bare drive-letter paths ("d:...");
// import specifiers must be file:// URLs.
const { RawToolDefinitionSchema, SharedPolicyPackSchema } = await tsImport(
  pathToFileURL(join(root, "src/lib/tool-registry/schema.ts")).href,
  import.meta.url,
);

function fail(msg) {
  console.error(`generate-tool-imports: ${msg}`);
  process.exit(1);
}

function assertSafeRel(rel, kind) {
  if (rel === "" || isAbsolute(rel))
    fail(`${kind} path must be repo-relative: "${rel}"`);
  if (rel.includes("..")) fail(`${kind} path must not traverse: "${rel}"`);
}

const manifestRaw = JSON.parse(await readFile(manifestPath, "utf8"));
const manifest =
  SharedPolicyPackSchema.shape.definitionsManifest.parse(manifestRaw);

// Shared policy packs (excluding manifest.json itself, which is part of the
// pack set, and _rules/).
const sharedNames = [
  "platform-profiles.json",
  "generic-reader-defaults.json",
  "scanner-policy.json",
  "skill-market-policy.json",
  "usage-taxonomy.json",
];
const sharedRaw = {};
for (const name of sharedNames) {
  const abs = join(defsDir, "_shared", name);
  try {
    sharedRaw[name] = JSON.parse(await readFile(abs, "utf8"));
  } catch (e) {
    fail(`cannot read/parse _shared/${name}: ${e.message}`);
  }
}
const sharedPacks = SharedPolicyPackSchema.parse({
  platformProfiles: sharedRaw["platform-profiles.json"],
  genericReaderDefaults: sharedRaw["generic-reader-defaults.json"],
  scannerPolicy: sharedRaw["scanner-policy.json"],
  skillMarketPolicy: sharedRaw["skill-market-policy.json"],
  usageTaxonomy: sharedRaw["usage-taxonomy.json"],
  definitionsManifest: manifest,
});

// Tool definitions in manifest order.
const seenIds = new Set();
const defs = [];
for (const entry of manifest.tools) {
  assertSafeRel(entry.path, `tool "${entry.id}"`);
  if (seenIds.has(entry.id))
    fail(`duplicate tool id "${entry.id}" in manifest`);
  seenIds.add(entry.id);
  const abs = join(defsDir, entry.path);
  let raw;
  try {
    raw = JSON.parse(await readFile(abs, "utf8"));
  } catch (e) {
    fail(`cannot read/parse ${entry.path}: ${e.message}`);
  }
  const parsed = RawToolDefinitionSchema.safeParse(raw);
  if (!parsed.success) {
    fail(
      `${entry.path} failed schema validation:\n${JSON.stringify(parsed.error.format(), null, 2)}`,
    );
  }
  if (parsed.data.id !== entry.id) {
    fail(
      `${entry.path} has id "${parsed.data.id}" but manifest says "${entry.id}"`,
    );
  }
  defs.push(parsed.data);
}
if (defs.length !== manifest.tools.length) {
  fail(
    `expected ${manifest.tools.length} definitions from manifest, got ${defs.length}`,
  );
}

// Canonical hash input: manifest + shared packs + definitions, deterministic
// key order (sorted paths) - any JSON change alters the version (docs §8.1).
const sortedDefs = [...defs].sort((a, b) => a.id.localeCompare(b.id));
const canonical = JSON.stringify({
  manifest,
  sharedPacks,
  definitions: sortedDefs,
});
const version = createHash("sha256")
  .update(canonical)
  .digest("hex")
  .slice(0, 16);

const banner =
  "// @generated by scripts/generate-tool-imports.mjs - DO NOT EDIT.\n";
const body = `import type { RawToolDefinition, SharedPolicyPacks } from "./schema.ts";

export const RAW_TOOL_DEFINITIONS: readonly RawToolDefinition[] = ${JSON.stringify(defs, null, 2)};

export const SHARED_POLICY_PACKS: SharedPolicyPacks = ${JSON.stringify(sharedPacks, null, 2)};

export const TOOL_REGISTRY_VERSION: string = ${JSON.stringify(version)};
`;
await writeFile(outPath, banner + body, "utf8");

console.log("generate-tool-imports");
console.log("─────────────────────────────────────────");
console.log(`definitions:        ${defs.length}`);
console.log(
  `  visible:          ${defs.filter((d) => d.catalogVisible !== false).length}`,
);
console.log(
  `  legacy hidden:    ${defs.filter((d) => d.catalogVisible === false).length}`,
);
console.log(`shared packs:       ${Object.keys(sharedPacks).length}`);
console.log(`registry version:   ${version}`);
console.log(`wrote ${relative(root, outPath)}`);
